import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:zan/Config/Routes/route_name.dart';import 'package:zan/main.dart';import '../../../../Core/Utils/Extensions/context_extension.dart';import '../../../../Core/Resources/app_colors.dart';import '../../../../Core/Resources/app_fonts.dart';import '../../../../Core/Resources/app_icons.dart';class SliverAppBarHome extends StatelessWidget {  const SliverAppBarHome({    super.key,  });  @override  Widget build(BuildContext context) {    return SliverAppBar(      backgroundColor: AppColors.backgroundColor,      scrolledUnderElevation: 0,      pinned: true,      leading: CircleAvatar(radius: 24.r),      title: Column(        crossAxisAlignment: CrossAxisAlignment.start,        children: [          Text(            "Client Name",            style: AppTextStyles.h6SemiBold,          ),          Text(            context.getGreeting(),            style: AppTextStyles.bodyXtraSmallMedium.copyWith(              color: AppColors.grayscale80,            ),          ),        ],      ),      elevation: 0,      actions: [        AppIcons.notification,        12.horizontalSpace,        InkWell(            onTap: () => kNavigationService.navigateTo(AppRoutes.cart),            child: AppIcons.bag),      ],    );  }}